        // [ K_B + lambda G   M_A^T ] [ u   ] = [ f_B ]
        // [ M_A              0     ] [ eta ]   [ g_A ]
        // =================================================

        const Eigen::Index kktSize =
            static_cast<Eigen::Index>(
                reducedSize +
                primaryCount);

